import { isPrimaryPointer } from "motion-dom";
export function extractEventInfo(event) {
    return {
        point: {
            x: event.pageX,
            y: event.pageY,
        },
    };
}
export const addPointerInfo = (handler) => (event) => {
    const pointerEvent = event;
    if (isPrimaryPointer(pointerEvent))
        handler(pointerEvent, extractEventInfo(pointerEvent));
};
